## Data model

Run this in Supabase SQL editor:

```sql
-- Profiles (extends auth.users)
create table profiles (
  id uuid primary key references auth.users on delete cascade,
  username text unique not null,
  display_name text,
  avatar_url text,
  bio text,
  created_at timestamptz default now()
);

-- Workouts
create table workouts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references profiles(id) on delete cascade,
  type text not null, -- 'run', 'lift', 'cycle', 'yoga', etc.
  title text,
  notes text,
  duration_seconds int not null,
  distance_meters numeric,
  calories int,
  started_at timestamptz not null,
  created_at timestamptz default now()
);

create index on workouts (user_id, started_at desc);

-- Follows
create table follows (
  follower_id uuid not null references profiles(id) on delete cascade,
  following_id uuid not null references profiles(id) on delete cascade,
  created_at timestamptz default now(),
  primary key (follower_id, following_id),
  check (follower_id <> following_id)
);

create index on follows (following_id);

-- Likes
create table workout_likes (
  workout_id uuid not null references workouts(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  created_at timestamptz default now(),
  primary key (workout_id, user_id)
);

-- Comments
create table workout_comments (
  id uuid primary key default gen_random_uuid(),
  workout_id uuid not null references workouts(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  body text not null,
  created_at timestamptz default now()
);

create index on workout_comments (workout_id, created_at);
```

## Row Level Security

Critical — Supabase exposes your DB directly to clients, so RLS is your auth layer:

```sql
alter table profiles enable row level security;
alter table workouts enable row level security;
alter table follows enable row level security;
alter table workout_likes enable row level security;
alter table workout_comments enable row level security;

-- Profiles: anyone can read, only owner can update
create policy "profiles_read" on profiles for select using (true);
create policy "profiles_insert" on profiles for insert with check (auth.uid() = id);
create policy "profiles_update" on profiles for update using (auth.uid() = id);

-- Workouts: visible to everyone (public app), owner controls writes
create policy "workouts_read" on workouts for select using (true);
create policy "workouts_insert" on workouts for insert with check (auth.uid() = user_id);
create policy "workouts_update" on workouts for update using (auth.uid() = user_id);
create policy "workouts_delete" on workouts for delete using (auth.uid() = user_id);

-- Follows: anyone reads, you control your own follows
create policy "follows_read" on follows for select using (true);
create policy "follows_insert" on follows for insert with check (auth.uid() = follower_id);
create policy "follows_delete" on follows for delete using (auth.uid() = follower_id);

-- Likes / comments
create policy "likes_read" on workout_likes for select using (true);
create policy "likes_insert" on workout_likes for insert with check (auth.uid() = user_id);
create policy "likes_delete" on workout_likes for delete using (auth.uid() = user_id);

create policy "comments_read" on workout_comments for select using (true);
create policy "comments_insert" on workout_comments for insert with check (auth.uid() = user_id);
create policy "comments_delete" on workout_comments for delete using (auth.uid() = user_id);
```

## Auto-create profile on signup

```sql
create function handle_new_user() returns trigger
language plpgsql security definer as $$
begin
  insert into profiles (id, username, display_name)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'username', 'user_' || substr(new.id::text, 1, 8)),
    new.raw_user_meta_data->>'display_name'
  );
  return new;
end; $$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_user();
```

## Feed view (your friends + you)

```sql
create or replace view feed_workouts as
select
  w.*,
  p.username,
  p.display_name,
  p.avatar_url,
  (select count(*) from workout_likes where workout_id = w.id) as like_count,
  (select count(*) from workout_comments where workout_id = w.id) as comment_count
from workouts w
join profiles p on p.id = w.user_id;
```

