## Feed query

**`hooks/use-feed.ts`:**
```ts
import { useInfiniteQuery } from '@tanstack/react-query';
import { supabase } from '@/lib/supabase';
import { FeedWorkout } from '@/lib/types';

const PAGE_SIZE = 20;

export function useFeed(userId: string) {
  return useInfiniteQuery({
    queryKey: ['feed', userId],
    initialPageParam: 0,
    queryFn: async ({ pageParam }) => {
      // Get who I follow + myself
      const { data: follows } = await supabase
        .from('follows')
        .select('following_id')
        .eq('follower_id', userId);

      const ids = [userId, ...(follows?.map((f) => f.following_id) ?? [])];

      const { data, error } = await supabase
        .from('feed_workouts')
        .select('*')
        .in('user_id', ids)
        .order('started_at', { ascending: false })
        .range(pageParam, pageParam + PAGE_SIZE - 1);

      if (error) throw error;
      return data as FeedWorkout[];
    },
    getNextPageParam: (last, all) =>
      last.length < PAGE_SIZE ? undefined : all.length * PAGE_SIZE,
  });
}
```

## Log workout mutation

**`hooks/use-log-workout.ts`:**
```ts
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/lib/supabase';
import { WorkoutType } from '@/lib/types';

interface LogWorkoutInput {
  type: WorkoutType;
  title?: string;
  notes?: string;
  duration_seconds: number;
  distance_meters?: number;
  calories?: number;
  started_at: string;
}

export function useLogWorkout(userId: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: LogWorkoutInput) => {
      const { data, error } = await supabase
        .from('workouts')
        .insert({ ...input, user_id: userId })
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: () => qc.invalidateQueries({ queryKey: ['feed'] }),
  });
}
```

