**`app/(tabs)/index.tsx` (feed):**
```tsx
import { FlatList, RefreshControl, Text, View } from 'react-native';
import { useAuth } from '@/hooks/use-auth';
import { useFeed } from '@/hooks/use-feed';
import { WorkoutCard } from '@/components/workout-card';

export default function FeedScreen() {
  const { user } = useAuth();
  const { data, fetchNextPage, hasNextPage, refetch, isRefetching } = useFeed(user!.id);
  const workouts = data?.pages.flat() ?? [];

  return (
    <FlatList
      data={workouts}
      keyExtractor={(w) => w.id}
      renderItem={({ item }) => <WorkoutCard workout={item} />}
      onEndReached={() => hasNextPage && fetchNextPage()}
      onEndReachedThreshold={0.5}
      refreshControl={<RefreshControl refreshing={isRefetching} onRefresh={refetch} />}
      ListEmptyComponent={
        <View className="p-8 items-center">
          <Text className="text-gray-500">Follow friends to see their workouts</Text>
        </View>
      }
    />
  );
}
```

## What I'd tackle next (in order)

1. **Auth screens** — email/password via Supabase, plus Apple Sign In (required by App Store if you offer Google/email)
2. **WorkoutCard component** + workout detail screen with likes/comments
3. **Discover/search** — search profiles by username
4. **Log workout form** — pick type, duration, optional GPS for runs/rides
5. **GPS tracking** — `expo-location` for real-time runs (this is where you'll outgrow Expo Go and need a dev build)
6. **Push notifications** — `expo-notifications` for likes/follows/comments
7. **Strava/Apple Health import** — biggest acquisition driver for fitness apps

